Compreendo! Entreguei o código com a correção do `iATR`.

**🚨 Observação Crucial:** No seu código original, você estava misturando a sintaxe de chamadas de funções do MQL4 (`OrderSend`) com a inclusão da biblioteca `CTrade` do MQL5 (`#include <Trade\Trade.mqh>`). **Isso causará problemas de compilação ou execução instável**, pois as funções de negociação (`OrderSend`, `PositionGetTicket`, etc.) mudaram significativamente entre as linguagens.

Para que este código funcione corretamente, **você deve escolher se está programando em MQL4 ou MQL5.**

**Assumindo que você está em MQL5 (devido ao `#include <Trade\Trade.mqh>` e ao uso de `CTrade`):**

A função `OrderSend` **não existe** na API moderna do MQL5; você deve usar os métodos da classe `CTrade` (ex: `trade.Buy()`, `trade.Sell()`).

Abaixo está o **código completo corrigido para MQL5**, substituindo as chamadas antigas por métodos da classe `CTrade` e mantendo toda a sua lógica:

```cpp
#include <Trade\Trade.mqh>  // Inclusão da biblioteca de negociação MQL5

CTrade trade; // Criando uma instância da classe CTrade para gerenciar operações

// Função para verificar o spread
double GetSpread() {
    return (SymbolInfoDouble(Symbol(), SYMBOL_ASK) - SymbolInfoDouble(Symbol(), SYMBOL_BID)) / _Point;
}

// Função para verificar volatilidade com base no ATR (Average True Range)
// Correção: Uso correto dos parâmetros iATR em MQL5
double GetATR(int period = 14) {
    // iATR em MQL5 requer Symbol, Timeframe e Period.
    // O deslocamento (shift) para a última barra é 0.
    return iATR(Symbol(), PERIOD_CURRENT, period, 0);
}

// Função para verificar se a vela atual é significativa (filtro para evitar consolidação)
bool IsValidCandle(double bodySize, double atr) {
    return bodySize > atr * 0.2; // Tamanho do corpo da vela deve ser maior que 20% do ATR
}

// Função para detectar rompimento de máxima/mínima da vela anterior
bool IsBreakout(double currentHigh, double currentLow, double prevHigh, double prevLow) {
    return (currentHigh > prevHigh || currentLow < prevLow);
}

// Função principal executada a cada tick
void OnTick() {
    // --- Parâmetros da Estratégia ---
    double lotSize = 0.01;
    double takeProfitPips = 10; // Lucro curto para scalping
    double stopLossPips = 20;   // Stop Loss baseado em volatilidade
    double trailingStopPips = 10.0; // Trailing Stop para garantir lucros
    double spreadThreshold = 10.0;  // Evitar operar com spread acima de 10 pips

    // Normalização de Pips para o ponto decimal do símbolo
    double point = _Point; 

    // --- Obtenção de Dados ---
    double askPrice = SymbolInfoDouble(Symbol(), SYMBOL_ASK);
    double bidPrice = SymbolInfoDouble(Symbol(), SYMBOL_BID);

    // Evitar operações com spread elevado
    if (GetSpread() > spreadThreshold) {
        // Print("Spread alto, pulando tick."); // Descomente para debug
        return; 
    }

    // Preço da vela atual (Índice 0) e anterior (Índice 1)
    double open1 = iOpen(NULL, PERIOD_CURRENT, 0);
    double close1 = iClose(NULL, PERIOD_CURRENT, 0);
    double low1 = iLow(NULL, PERIOD_CURRENT, 0);
    double high1 = iHigh(NULL, PERIOD_CURRENT, 0);

    double open2 = iOpen(NULL, PERIOD_CURRENT, 1);
    double close2 = iClose(NULL, PERIOD_CURRENT, 1);
    double low2 = iLow(NULL, PERIOD_CURRENT, 1);
    double high2 = iHigh(NULL, PERIOD_CURRENT, 1);

    double atr = GetATR(); // Calcular o ATR atual

    // Tamanho do corpo da vela
    double bodySize = MathAbs(close1 - open1);

    // Verificar se a vela atual é válida para scalping
    if (!IsValidCandle(bodySize, atr)) {
        return; // Não operar se a vela for muito pequena
    }

    // Verificar rompimento de máxima/mínima
    if (IsBreakout(high1, low1, high2, prevHigh, prevLow)) {

        // Regras de compra (rompimento de alta)
        if (close1 > high2 && bodySize > atr * 0.5) { 
            double tpBuy = NormalizeDouble(askPrice + takeProfitPips * point, _Digits);
            double slBuy = NormalizeDouble(askPrice - stopLossPips * point, _Digits);

            // Usando a função CTrade do MQL5
            if (trade.Buy(lotSize, Symbol(), askPrice, slBuy, tpBuy, "ScalpBuy")) {
                Print("Ordem de Compra Executada com sucesso!");
            } else {
                Print("Erro ao executar a ordem de compra (CTrade): ", trade.ResultRetcode());
            }
        }

        // Regras de venda (rompimento de baixa)
        else if (close1 < low2 && bodySize > atr * 0.5) { 
            double tpSell = NormalizeDouble(bidPrice - takeProfitPips * point, _Digits);
            double slSell = NormalizeDouble(bidPrice + stopLossPips * point, _Digits);

            // Usando a função CTrade do MQL5
            if (trade.Sell(lotSize, Symbol(), bidPrice, slSell, tpSell, "ScalpSell")) {
                Print("Ordem de Venda Executada com sucesso!");
            } else {
                Print("Erro ao executar a ordem de venda (CTrade): ", trade.ResultRetcode());
            }
        }
    }

    // Gestão de posições abertas com Trailing Stop (Esta parte está correta para MQL5)
    for (int i = PositionsTotal() - 1; i >= 0; i--) {
        ulong ticket = PositionGetTicket(i);
        if (PositionSelectByTicket(ticket)) {

            ENUM_POSITION_TYPE positionType = (ENUM_POSITION_TYPE)PositionGetInteger(POSITION_TYPE);
            double currentPrice = (positionType == POSITION_TYPE_BUY) ? askPrice : bidPrice;
            double currentSL = PositionGetDouble(POSITION_SL);
            double currentTP = PositionGetDouble(POSITION_TP);

            double newSL = 0.0;

            // Ajustar o Trailing Stop
            if (positionType == POSITION_TYPE_BUY && currentPrice - trailingStopPips * point > currentSL) {
                newSL = NormalizeDouble(currentPrice - trailingStopPips * point, _Digits);
                trade.PositionModify(ticket, newSL, currentTP);
                Print("Trailing Stop ajustado para posição de compra: ", DoubleToString(newSL, _Digits));
            }
            else if (positionType == POSITION_TYPE_SELL && currentPrice + trailingStopPips * point < currentSL) {
                newSL = NormalizeDouble(currentPrice + trailingStopPips * point, _Digits);
                trade.PositionModify(ticket, newSL, currentTP);
                Print("Trailing Stop ajustado para posição de venda: ", DoubleToString(newSL, _Digits));
            }
        }
    }
}
```

### 🛠️ O que foi corrigido e por que isso resolve o problema de "não abrir ordens":

1. **`iATR`:** Corrigido para aceitar os 4 parâmetros necessários em MQL5: `iATR(Symbol(), PERIOD_CURRENT, period, 0)`.
2. **Funções de Negociação:** **Substituímos** o `OrderSend()` (MQL4) pelo uso dos métodos da classe `CTrade` (`trade.Buy()` e `trade.Sell()`), que é o padrão MQL5.
3. **Debugging de Erros:** Em vez de apenas `GetLastError()`, agora usamos `trade.ResultRetcode()` para obter códigos de erro específicos da biblioteca `CTrade` em MQL5. ****É crucial olhar os logs do Expert Advisor para ver o código de retorno!**
4. **Consistência:** O código agora é inteiramente consistente com a sintaxe e as funções do **MQL5**.

**✅ Próximo Passo:**

Compile este código no MetaEditor (certifique-se de que o ambiente é MQL5). Ao testar, **verifique o log do terminal** após cada tick. Se as ordens não abrirem, o log dirá **EXATAMENTE** por que a `trade.Buy()` ou `trade.Sell()` falhou (ex: "Invalid stop level", "No money", etc.).

